"""``workpeg project submit``, ``project status`` and ``project versions``.

A peg version is one upload: the peg's Python source, UI and function and
``workpeg.json`` together. Workpeg is to build it itself, with its own
builder, at the SDK the peg targets, and nothing a developer built goes live
(owner, 2026-11-02). That builder is slice 3 and does not exist yet, but what
is sent is already what it will need. So this command packs SOURCE and
nothing else:

- the root ``workpeg.json``, and the ``ui/``, ``function/`` and ``assets/``
  folders, and nothing else at the root;
- never a local build: ``build/`` and ``dist/`` are dropped at the roots of
  ``ui/`` and ``function/``, and the courtesy build below is written to a
  folder outside the project and deleted;
- never a secret or a symlink, and nothing that is not a regular file; a
  hard link is refused unread, since its bytes may be a file outside the
  peg;
- ``function/`` exactly as ``function submit`` would send it: its folders
  too, and the ``.gitkeep`` that keeps an empty one, since a Dockerfile can
  ``COPY`` a folder that holds nothing else.

LOCAL CHECKS ARE A COURTESY. Workpeg's pipeline is to run every one of them
again on what arrives; today the function's checks also run again when a
business installs it. They are here because a version, once uploaded, is
never replaced: a version Workpeg would refuse burns its number. They are:

- the ``sdk`` key (:func:`target_sdk.require`), with the mismatch warning;
- the refusals Workpeg applies to an upload before it builds anything that
  can be seen from the file list (what may be in ``ui/`` and ``assets/``,
  names, sizes);
- ``function_check.check_bundle`` on ``function/`` exactly as it is packed,
  unpacked into a temporary folder;
- a build of the packed ``ui/`` with chrome ``auto``, thrown away.

THE UPLOAD is the registry's peg version routes (repo.workpeg.com,
``pegs/version_views.py``): declare the version with the archive's size and
sha256, which creates the row and answers a presigned POST for the private
bucket bound to exactly those; post the archive straight to the bucket with
those fields and nothing else (never the Key); then tell the registry it is
done, and it checks S3's own checksum. A development version stops there,
stored; a main version is queued for Workpeg's build and then its review.
The bytes never pass through the registry. A declared version whose upload
did not finish is finished by running the same command again: the same
declaration answers a fresh POST. And a version the registry already
recorded with exactly these bytes, because its answer was lost or the
command simply ran twice, is reported as submitted, with its state, and
nothing is sent again: the registry answers any declaration of a recorded
version "already exists", so the SDK asks it what the version holds.

``status`` and ``versions`` read the same routes and say each version's
state in plain words. Nothing the registry answers that holds a presigned
policy or link is ever printed.
"""
from __future__ import annotations

import gzip
import hashlib
import io
import json
import os
import re
import stat
import sys
import tarfile
import tempfile
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional
from urllib.parse import quote, urlsplit

import requests

from workpeg import submit, target_sdk

__all__ = [
    "ASSET_SUFFIXES", "MAX_ENTRIES", "MAX_UNPACKED_BYTES",
    "MAX_UPLOAD_BYTES", "Packed", "ROOT_ENTRIES", "UI_SCRIPT_SUFFIXES",
    "main_status", "main_submit", "main_versions", "pack", "state_of",
    "status_line", "submitted_line",
]

#: The upload cap, on the compressed archive (owner, 2026-11-12, decision
#: 13). Workpeg's own cap is the one that counts; this one saves the trip.
MAX_UPLOAD_BYTES = 20 * 1024 * 1024

#: Workpeg's caps on what an upload unpacks to (decision 13).
MAX_UNPACKED_BYTES = 60 * 1024 * 1024
MAX_ENTRIES = 5000

#: What a peg version is made of, at the project's root. Anything else there
#: (AGENTS.md, a README, the git folder) is the developer's, not the peg's.
ROOT_ENTRIES = ("workpeg.json", "ui", "function", "assets")

#: Never packed, at any depth: ``function submit``'s list without ``build``
#: and ``dist``, plus editor, tool and cache folders.
EXCLUDED_NAMES = submit.ALWAYS_EXCLUDED | frozenset({
    "node_modules", ".idea", ".vscode", ".tox", ".ruff_cache", ".coverage",
})

#: Local build output, dropped only at the root of these folders: a
#: ``dist/`` deeper down is source like any other, and Workpeg judges it.
BUILD_OUTPUT = frozenset({"build", "dist"})
BUILD_OUTPUT_ROOTS = ("ui", "function")

#: Files an operating system or git leaves in a folder (build._LITTER_NAMES).
_LITTER = frozenset({
    ".ds_store", "thumbs.db", "desktop.ini", ".gitkeep", ".gitignore",
})

#: What is litter inside ``function/``: none of git's files, which keep a
#: folder the Dockerfile may ``COPY`` (``function submit`` keeps them too).
_FUNCTION_LITTER = _LITTER - {".gitkeep", ".gitignore"}

#: The prefixes no folder or Python module under ``ui/`` may have, at any
#: depth, case folded: the SDK's name and its libraries' (``workpeg_*``).
_SDK_NAME = "workpeg"
_LIBRARY_PREFIX = "workpeg_"

#: What runs in a browser. A peg is Python only (DEC-82), so Workpeg refuses
#: any of these under ``ui/``, ``public/`` included.
UI_SCRIPT_SUFFIXES = (".js", ".mjs", ".html", ".htm", ".css", ".svg",
                      ".wasm")

#: What ``assets/`` may hold, by final suffix: the registry's CDN route's
#: own list (reg:cdn/peg_assets.py ``ALLOWED_TYPES``), since that is where
#: the publisher puts these files. Pictures and data, and nothing a browser
#: runs. An allow-list, as the registry's is: a deny-list has to know every
#: type each browser will run. An SVG's content, and where a logo must sit,
#: are Workpeg's to check; this only saves a version number.
ASSET_SUFFIXES = frozenset({
    ".svg", ".png", ".jpg", ".jpeg", ".gif", ".webp", ".avif", ".bmp",
    ".ico", ".json", ".txt",
})


def _looks_secret(name: str) -> bool:
    """``function submit``'s list, plus the JSON key files cloud consoles
    hand out: a service account's, a Firebase admin SDK's, an OAuth
    client's, and anything named for credentials."""
    lo = name.lower()
    if submit._looks_secret(name) or lo == "secrets.json":
        return True
    return lo.endswith(".json") and (
        "service-account" in lo or "firebase-adminsdk" in lo
        or lo.startswith("client_secret") or "credentials" in lo)


class Refused(Exception):
    """Workpeg would refuse this upload. The message says which file and
    what to do about it."""


@dataclass
class Packed:
    """One packed peg version, and its function half."""
    archive: bytes
    sha256: str
    files: list
    unpacked: int
    skipped: list = field(default_factory=list)
    left_out: list = field(default_factory=list)
    function: Optional[bytes] = None
    function_sha256: Optional[str] = None
    function_files: list = field(default_factory=list)
    #: ``{name: bytes}`` for the courtesy build.
    contents: dict = field(default_factory=dict)


def _tar_gz(entries, folders=()) -> bytes:
    """A gzip'd ustar archive of *entries* (``(name, data, mode)``) and
    *folders* (names), the same bytes every time: sorted, owner and time
    fixed, regular files and folders only. So ``--dry-run`` prints the
    digest the real upload has."""
    raw = io.BytesIO()
    items = [(name, data, mode) for name, data, mode in entries]
    items += [(name, None, 0o755) for name in folders]
    with tarfile.open(fileobj=raw, mode="w",
                      format=tarfile.USTAR_FORMAT) as tar:
        for name, data, mode in sorted(items, key=lambda item: item[0]):
            info = tarfile.TarInfo(name)
            info.mode = mode
            info.mtime = 0
            info.uid = info.gid = 0
            info.uname = info.gname = ""
            if data is None:
                info.type = tarfile.DIRTYPE
            else:
                info.type = tarfile.REGTYPE
                info.size = len(data)
            try:
                tar.addfile(info, io.BytesIO(data) if data is not None
                            else None)
            except ValueError as exc:
                raise Refused(
                    f"{name}: {exc}. Workpeg takes a name of up to 100 "
                    "characters after its last folder, and 255 in all; "
                    "shorten it.") from None
    return gzip.compress(raw.getvalue(), compresslevel=9, mtime=0)


def _read(path: Path) -> bytes:
    """*path*'s bytes, refusing to follow a link that appeared since it was
    looked at."""
    fd = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    with os.fdopen(fd, "rb") as handle:
        return handle.read()


def _ui_refusal(rel: str) -> Optional[str]:
    """Why Workpeg refuses the file at *rel* (under ``ui/``), or None."""
    from workpeg.ui.build import PUBLIC_SUFFIXES

    parts = rel.split("/")
    inside = parts[1:]
    top = inside[0]
    if inside == ["workpeg.json"]:
        return (f"{rel} would stand in for the peg's own workpeg.json: the "
                "build reads the one beside main.py first. Move what it says "
                "into the workpeg.json at the root and delete it.")
    taken = _sdk_named(inside)
    if taken is not None:
        return (f"{rel}: {taken} has the name of the SDK or a Workpeg "
                "library, so it could stand in for code the reviewer reads "
                "as Workpeg's, in any page beside it. Rename it.")
    suffix = os.path.splitext(parts[-1])[1].lower()
    if suffix in UI_SCRIPT_SUFFIXES:
        return (f"{rel}: a peg is Python only, and Workpeg refuses any "
                + ", ".join(UI_SCRIPT_SUFFIXES) + " file under ui/.")
    if suffix in (".py", ".json"):
        return None
    if top == "public" and len(inside) > 1:
        if suffix == ".pdf":
            return (f"{rel}: Workpeg does not take a PDF in public/ yet, "
                    "because what a PDF can run has not been measured.")
        if suffix in PUBLIC_SUFFIXES:
            return None
    allowed = sorted(PUBLIC_SUFFIXES - {".pdf"})
    return (f"{rel}: ui/ holds Python (.py), .json, and public/ files "
            f"Workpeg serves as they are ({' '.join(allowed)}). Move it out "
            "of ui/.")


def _asset_refusal(rel: str) -> Optional[str]:
    """Why Workpeg refuses the file at *rel* (under ``assets/``), or None.
    """
    name = rel.rsplit("/", 1)[-1]
    _, dot, extension = name.rpartition(".")
    if dot and f".{extension.lower()}" in ASSET_SUFFIXES:
        return None
    return (f"{rel}: a peg is Python only, and assets/ goes to Workpeg's CDN "
            "as pictures and data, so it takes only "
            + " ".join(sorted(ASSET_SUFFIXES)) + " files. Move it out of "
            "assets/.")


def _sdk_named(inside: list) -> Optional[str]:
    """The part of a path under ``ui/`` (its parts, *inside*) named like the
    SDK or a library, or None: a folder ``workpeg`` or ``workpeg_*``, or a
    module ``workpeg.py`` or ``workpeg_*.py``, at any depth.

    At any depth, because the resolver every target from 0.150.0 to 0.160.0
    runs reads an import from the importing page's own folder first, so
    ``ui/pages/workpeg_phone.py`` stands in for the library in every page
    under ``ui/pages/``. Case folded, for a case-blind disk. A ``.json`` or
    public file of such a name is not importable and is left alone."""
    for index, part in enumerate(inside):
        last = index == len(inside) - 1
        name = part.lower()
        if last:
            if not name.endswith(".py"):
                return None
            name = name[:-3]
        if name == _SDK_NAME or name.startswith(_LIBRARY_PREFIX):
            return "/".join(inside[:index + 1]) + ("" if last else "/")
    return None


def _check_names(rels) -> None:
    """Refuse a name Workpeg refuses: one outside printable ASCII or holding
    a character that means something in a URL (the verifier's own rule), or
    two that differ only in case, which a case-blind disk would make one
    file."""
    from workpeg.ui.verify import _name_problem

    seen = {}
    for rel in rels:
        if not rel.isascii():
            raise Refused(f"{rel}: Workpeg takes only ASCII file names.")
        why = _name_problem(rel)
        if why is not None:
            raise Refused(f"{rel!r}: Workpeg refuses this name: {why}")
        other = seen.setdefault(rel.lower(), rel)
        if other != rel:
            first, second = sorted((rel, other))
            raise Refused(f"{first} and {second} differ only in case, and "
                          "Workpeg takes only one of them. Rename one.")


def pack(project_dir) -> Packed:
    """Pack *project_dir* as a peg version, or :class:`Refused`."""
    root = Path(project_dir)
    manifest = root / "workpeg.json"
    try:
        st = os.lstat(manifest)
    except FileNotFoundError:
        raise Refused(f"There is no workpeg.json in {root}.") from None
    if not stat.S_ISREG(st.st_mode):
        raise Refused("workpeg.json at the root is not a regular file.")

    found = []        # (rel, path, st)
    folders = []      # function/ folders, kept as folders in its bundle
    skipped = []
    try:
        names = sorted(os.listdir(root))
    except OSError as exc:
        raise Refused(f"{root} cannot be read: {exc}") from None
    left_out = [n for n in names if n not in ROOT_ENTRIES
                and n.lower() not in _LITTER]
    found.append(("workpeg.json", manifest, st))
    for top in ROOT_ENTRIES[1:]:
        base = root / top
        try:
            top_st = os.lstat(base)
        except FileNotFoundError:
            continue
        if stat.S_ISLNK(top_st.st_mode):
            skipped.append(f"{top} (symlink)")
            continue
        if not stat.S_ISDIR(top_st.st_mode):
            raise Refused(f"{top} at the root is not a folder.")
        for dirpath, dirnames, filenames in os.walk(base, followlinks=False):
            rel_dir = Path(dirpath).relative_to(root).as_posix()
            keep = []
            for d in sorted(dirnames):
                rel = f"{rel_dir}/{d}"
                if d in EXCLUDED_NAMES:
                    continue
                if rel_dir in BUILD_OUTPUT_ROOTS and d in BUILD_OUTPUT:
                    continue
                if os.path.islink(os.path.join(dirpath, d)):
                    skipped.append(f"{rel} (symlink)")
                    continue
                keep.append(d)
                if top == "function":
                    folders.append(rel)
            dirnames[:] = keep
            litter = _FUNCTION_LITTER if top == "function" else _LITTER
            for f in sorted(filenames):
                rel = f"{rel_dir}/{f}"
                path = Path(dirpath) / f
                if f in EXCLUDED_NAMES or f.lower() in litter:
                    continue
                if rel_dir in BUILD_OUTPUT_ROOTS and f in BUILD_OUTPUT:
                    continue
                fst = os.lstat(path)
                if stat.S_ISLNK(fst.st_mode):
                    skipped.append(f"{rel} (symlink)")
                    continue
                if not stat.S_ISREG(fst.st_mode):
                    skipped.append(f"{rel} (not a regular file)")
                    continue
                if _looks_secret(f):
                    skipped.append(rel)
                    continue
                if fst.st_nlink != 1:
                    raise Refused(
                        f"{rel} is a hard link, so its bytes may be a file "
                        "outside the peg, and Workpeg refuses one. Replace "
                        "it with a copy.")
                found.append((rel, path, fst))

    _check_names([rel for rel, _path, _st in found] + folders)
    for rel, _path, _st in found:
        why = (_ui_refusal(rel) if rel.startswith("ui/")
               else _asset_refusal(rel) if rel.startswith("assets/")
               else None)
        if why:
            raise Refused(why)
    if len(found) > MAX_ENTRIES:
        raise Refused(f"The peg has {len(found):,} files, and Workpeg takes "
                      f"at most {MAX_ENTRIES:,}.")
    unpacked = sum(s.st_size for _r, _p, s in found)
    if unpacked > MAX_UNPACKED_BYTES:
        raise Refused(f"The peg's files come to {unpacked:,} bytes, and "
                      f"Workpeg takes at most {MAX_UNPACKED_BYTES:,}.")

    entries = []
    contents = {}
    for rel, path, fst in found:
        data = _read(path)
        mode = 0o755 if fst.st_mode & 0o111 else 0o644
        entries.append((rel, data, mode))
        contents[rel] = data
    archive = _tar_gz(entries)
    if len(archive) > MAX_UPLOAD_BYTES:
        raise Refused(f"The packed peg is {len(archive):,} bytes, and "
                      f"Workpeg takes at most {MAX_UPLOAD_BYTES:,}.")

    packed = Packed(
        archive=archive,
        sha256=hashlib.sha256(archive).hexdigest(),
        files=sorted(rel for rel, _d, _m in entries),
        unpacked=unpacked,
        skipped=sorted(skipped),
        left_out=left_out,
        contents=contents,
    )
    fn = [(rel[len("function/"):], data, mode)
          for rel, data, mode in entries if rel.startswith("function/")]
    if fn:
        packed.function = _tar_gz(
            fn, [rel[len("function/"):] for rel in folders])
        packed.function_sha256 = hashlib.sha256(packed.function).hexdigest()
        packed.function_files = sorted(name for name, _d, _m in fn)
    return packed


def _unpack(bundle: bytes, into: Path) -> Path:
    """Write the function *bundle* this module packed into *into*, folder
    by folder and file by file, and return the folder."""
    root = into / "function"
    root.mkdir()
    with tarfile.open(fileobj=io.BytesIO(bundle), mode="r:gz") as tar:
        for member in tar.getmembers():
            dest = root.joinpath(*member.name.split("/"))
            if member.isdir():
                dest.mkdir(parents=True, exist_ok=True)
                continue
            dest.parent.mkdir(parents=True, exist_ok=True)
            handle = tar.extractfile(member)
            dest.write_bytes(handle.read() if handle is not None else b"")
            os.chmod(dest, member.mode & 0o755)
    return root


def _local_build(packed: Packed, namespace: str) -> None:
    """Build the packed ``ui/`` as Workpeg will, with chrome ``auto``, in a
    folder outside the project, and throw the result away. Raises
    :class:`Refused` with the compiler's message when it does not compile.
    """
    from workpeg.ui.actions_manifest import ActionValidationError
    from workpeg.ui.build import PublicAssetError, build_ui
    from workpeg.ui.compiler.ast_parser import UnsupportedSyntaxError
    from workpeg.ui.search_manifest import ManifestValidationError

    errors = (UnsupportedSyntaxError, SyntaxError, ManifestValidationError,
              ActionValidationError, PublicAssetError, RuntimeError)
    with tempfile.TemporaryDirectory(prefix="workpeg-submit-") as tmp:
        src = Path(tmp) / "source"
        for rel, data in packed.contents.items():
            if rel == "workpeg.json" or rel.startswith("ui/"):
                dest = src / rel
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_bytes(data)
        try:
            build_ui(str(src / "ui" / "main.py"), str(Path(tmp) / "dist"),
                     peg_namespace=namespace, chrome_source="auto")
        except errors as exc:
            text = str(exc).replace(str(src) + os.sep, "")
            raise Refused(f"ui/ does not compile: {text}") from None


def _short(sha256: Optional[str]) -> str:
    return (sha256 or "unknown")[:12] + ("…" if sha256 else "")


def submitted_line(branch: str, version: str, sha256: Optional[str],
                   target: str) -> str:
    """The line after an upload, in the shape of ``function submit``'s.

    "Queued for Workpeg to build", not "Workpeg builds it": the builder is
    the next slice, and until it runs a main version waits in the queue."""
    ref = f"{branch}:{version}"
    if branch == submit.RELEASE_BRANCH:
        return (f"{ref} is submitted (sha256 {_short(sha256)}). It is queued "
                f"for Workpeg to build with SDK {target}, then it waits for "
                "review.")
    return (f"{ref} is stored for development only (sha256 "
            f"{_short(sha256)}); not built, reviewed or run on Workpeg.")


def _namespace(project: Path) -> str:
    try:
        data = json.loads((project / "workpeg.json").read_text(
            encoding="utf-8"))
    except (OSError, UnicodeDecodeError, ValueError) as exc:
        submit._fail(f"workpeg.json cannot be read: {exc}")
    ns = data.get("namespace") if isinstance(data, dict) else None
    if not isinstance(ns, str) or not ns:
        submit._fail('workpeg.json names no "namespace".')
    return ns


def _token_peg(namespace: Optional[str]) -> "tuple[str, str]":
    """``(token, peg)`` from ``WORKPEG_PK``, refusing a Key for another peg
    than the one in ``workpeg.json``."""
    token = os.environ.get(submit.JWT_ENV)
    if not token:
        submit._fail(f"Missing env var {submit.JWT_ENV}: your Key for this "
                     "peg (docs/functions.md#getting-a-token-workpeg_pk).")
    peg = submit.decode_jwt_payload_no_verify(token).get("peg_namespace")
    if not peg:
        submit._fail(f"{submit.JWT_ENV} names no peg_namespace.")
    if namespace is not None and peg != namespace:
        submit._fail(
            f"{submit.JWT_ENV} is a Key for {peg}, and workpeg.json is the "
            f"peg {namespace}. Use {namespace}'s Key, from the same "
            "developer account.")
    return token, str(peg)


def _api(api: Optional[str]) -> str:
    return (api or os.environ.get(submit.API_ENV, submit.DEFAULT_API_BASE)
            ).rstrip("/")


# ---------------------------------------------------------------- registry

#: Keys of a registry answer that hold a presigned policy or link. Never
#: printed: anyone holding one can write, or read, a version's bytes.
_PRESIGNED = ("upload", "download_url")


def _public(body):
    """*body* without anything presigned, at the top and in a list."""
    if not isinstance(body, dict):
        return body
    out = {k: v for k, v in body.items() if k not in _PRESIGNED}
    if isinstance(out.get("versions"), list):
        out["versions"] = [_public(v) for v in out["versions"]]
    return out


#: Characters a terminal acts on: C0 controls but the newline, DEL, and C1.
_CONTROL = re.compile(r"[\x00-\x09\x0b-\x1f\x7f-\x9f]")


def _plain(text) -> str:
    """*text* with nothing a terminal would act on. A build log quotes the
    developer's own source and a note is free text, so neither may carry
    an escape sequence to whoever reads it. A tab becomes a space."""
    return _CONTROL.sub(lambda m: " " if m.group() == "\t" else "",
                        str(text))


def _versions_path(peg: str, tail: str = "") -> str:
    return f"/api/pegs/{quote(peg, safe='')}/versions/{tail}"


def _call(method: str, api: str, peg: str, token: str, tail: str,
          timeout: int, body: Optional[dict] = None):
    """``(status, json or text)`` for one version route."""
    r = requests.request(
        method, api + _versions_path(peg, tail), json=body,
        headers={"Authorization": f"Bearer {token}"}, timeout=timeout)
    try:
        answer = r.json()
    except ValueError:
        answer = r.text
    return r.status_code, answer


def _detail_of(answer) -> str:
    if isinstance(answer, dict) and "detail" in answer:
        return _plain(answer["detail"])
    return _plain(str(answer)[:500])


def _no_routes(answer) -> bool:
    """A 404 that is the registry's URL table, not a version route: an
    unrouted URL is Django's HTML page, a route's own 404 is JSON."""
    return not (isinstance(answer, dict) and "detail" in answer)


def _no_versions_yet(api: str, peg: str, *, tail: str = "",
                     after: str = "") -> None:
    submit._fail(f"The registry at {api} does not take peg versions yet "
                 f"(404 for {_versions_path(peg, tail)}).{after}", code=1)


def _version_tail(branch: str, version: str, end: str = "") -> str:
    return f"{quote(branch, safe='')}/{quote(version, safe='')}/{end}"


#: The registry's own words (pegs/version_views.py, nm/repo-peg-versions
#: 1091731) for a main version it failed before any build ran: its upload
#: was never finished and a peg in review moved on (``UPLOAD_EXPIRED``),
#: or the bucket held other bytes than the ones declared
#: (``DIFFERENT_BYTES``). Such a version holds nothing Workpeg will build,
#: and it can never be declared again.
NEVER_BUILT = (
    "The upload was never finished, and the peg in review has taken a "
    "newer version instead, so this version will not be built.",
    "The stored bytes are not the ones declared, so this version will not "
    "be built. Submit a new version.",
)


def never_built(row: dict) -> bool:
    """True for a ``failed`` main version that no build ever saw: its
    upload never finished (``uploaded_at`` is null), or the registry
    refused its bytes. Its "failed" is not a build failing, and it is
    not a version that was submitted."""
    if row.get("build_status") != "failed":
        return False
    if not row.get("uploaded_at"):
        return True
    error = row.get("build_error")
    return isinstance(error, str) and error.strip() in NEVER_BUILT


def _taken(api, peg, token, branch, version, timeout):
    """The registry's row for *branch*:*version* when it is past
    uploading, else None. Any doubt, an error or a lost answer included,
    is None: the registry's refusal then stands."""
    try:
        code, answer = _call("GET", api, peg, token,
                             _version_tail(branch, version), timeout)
    except (requests.ConnectionError, requests.Timeout):
        return None
    if code != 200 or not isinstance(answer, dict):
        return None
    if answer.get("build_status") in (None, "uploading"):
        return None
    return answer


def _declare(api, peg, token, branch, version, packed, timeout):
    """``(upload, None)``: the registry's presigned POST for the declared
    version; or ``(None, row)`` when the registry already recorded this
    version with exactly these bytes. A version the registry failed
    before any build, whatever bytes it held, ends the command: it can
    never be submitted again."""
    ref = f"{branch}:{version}"
    code, answer = _call("POST", api, peg, token, "", timeout, body={
        "branch": branch, "version": version,
        "size": len(packed.archive), "sha256": packed.sha256})
    if code == 404 and _no_routes(answer):
        _no_versions_yet(api, peg, after=" Nothing was uploaded.")
    if code == 409:
        row = _taken(api, peg, token, branch, version, timeout)
        if row is not None and never_built(row):
            submit._fail(cannot_reuse_line(ref, _why_not_built(row)),
                         code=1)
        if row is not None and (row.get("size"), row.get("sha256")) == (
                len(packed.archive), packed.sha256):
            return None, row
    if code >= 400:
        submit._fail(f"The registry refused {ref} ({code}): "
                     f"{_detail_of(answer)} Nothing was uploaded.", code=1)
    upload = answer.get("upload") if isinstance(answer, dict) else None
    if not (isinstance(upload, dict) and isinstance(upload.get("url"), str)
            and isinstance(upload.get("fields"), dict)
            and all(isinstance(k, str) and isinstance(v, str)
                    for k, v in upload["fields"].items())):
        submit._fail(f"The registry's answer to {ref} holds no upload "
                     "address. Nothing was uploaded.", code=1)
    return upload, None


def cannot_reuse_line(ref: str, why: str) -> str:
    """What a re-run of a :func:`never_built` version says, after
    ``ERROR:``."""
    return (f"{ref} cannot be reused: {why} A version is declared once and "
            "never changes, so submit this peg as a new version. Nothing "
            "was uploaded.")


def _why_not_built(row: dict) -> str:
    """The registry's reason for a :func:`never_built` version, one line
    of plain text."""
    why = " ".join(_plain(row.get("build_error") or "").split())
    return why or ("Its upload was never finished, so Workpeg will not "
                   "build it.")


#: The hosts a presigned POST may name over plain http: this computer,
#: for a registry run locally. Anywhere else it must be https.
_LOOPBACK = frozenset({"127.0.0.1", "localhost", "::1"})


def _to_bucket(upload: dict, packed: Packed, ref: str, timeout: int) -> None:
    """POST the archive to the bucket with the registry's signed fields,
    file last as S3 requires, and no credential of ours: the signed policy
    is the whole authority, and the Key is the registry's alone."""
    parts = urlsplit(upload["url"])
    if not (parts.scheme == "https" or (
            parts.scheme == "http" and parts.hostname in _LOOPBACK)):
        submit._fail(f"The registry's upload address for {ref} is not https "
                     f"({parts.scheme}://{parts.hostname}/), so the archive "
                     "was not sent. Nothing was uploaded.", code=1)
    again = (f"{ref} is declared with these bytes and was not uploaded; run "
             "the same command again to finish it.")
    try:
        r = requests.post(
            upload["url"], data=upload["fields"],
            files={"file": ("upload.tar.gz", packed.archive,
                            "application/gzip")},
            timeout=timeout, allow_redirects=False)
    except (requests.ConnectionError, requests.Timeout) as exc:
        submit._fail(f"Could not reach the upload bucket for {ref}: "
                     f"{_plain(exc)}. {again}")
    if not 200 <= r.status_code < 300:
        found = {tag: re.search(rf"<{tag}>([^<]{{0,300}})</{tag}>", r.text)
                 for tag in ("Code", "Message")}
        why = " ".join(_plain(m.group(1)) for m in found.values() if m)
        said = f"{r.status_code} " + why.replace(" ", ": ", 1) if why \
            else str(r.status_code)
        submit._fail(f"The bucket refused the upload of {ref} ({said}). "
                     f"{again}", code=1)


def _uploaded(api, peg, token, branch, version, timeout) -> dict:
    """Tell the registry the bytes are in the bucket; its answer."""
    ref = f"{branch}:{version}"
    code, answer = _call("POST", api, peg, token,
                         _version_tail(branch, version, "uploaded/"),
                         timeout)
    if code >= 400:
        tail = ""
        if not isinstance(answer, dict) or answer.get(
                "build_status", "uploading") == "uploading":
            tail = " Run the same command again to finish it."
        submit._fail(f"The registry did not record the upload of {ref} "
                     f"({code}): {_detail_of(answer)}{tail}", code=1)
    if not isinstance(answer, dict):
        submit._fail(f"The registry answered something that is not a JSON "
                     f"object: {_plain(str(answer)[:200])}", code=1)
    return answer


def main_submit(ref: str, *, path: str = ".", dry_run: bool = False,
                api: Optional[str] = None, timeout: int = 60) -> int:
    """``workpeg project submit``. Exits through ``SystemExit`` on a
    refusal or a lost connection (2) or a registry error (1); returns 0,
    or 1 for a version already recorded with these bytes that failed."""
    from workpeg.cli import _warn_target
    from workpeg.build import validate_function_project
    from workpeg.function_check import BundleRefused, check_bundle

    branch, version = submit.parse_ref(ref)
    project = Path(path).resolve()
    try:
        target = target_sdk.require(project)
    except target_sdk.TargetError as exc:
        submit._fail(str(exc))
    _warn_target(target)
    namespace = _namespace(project)
    token = peg = None
    if not dry_run:
        token, peg = _token_peg(namespace)

    if not (project / "ui" / "main.py").is_file():
        submit._fail("There is no ui/main.py. project submit sends a whole "
                     "peg; a peg with only a function uses `workpeg "
                     "function submit`.")
    try:
        packed = pack(project)
    except Refused as exc:
        submit._fail(f"{exc} Nothing was uploaded.")
    if packed.skipped:
        print("  Skipped (looks like a secret, a symlink or not a file; "
              "not packed): " + ", ".join(packed.skipped), file=sys.stderr)

    if packed.function is not None:
        # On function/ as it is packed, never the folder on disk: a check
        # must see exactly what Workpeg will.
        with tempfile.TemporaryDirectory(prefix="workpeg-function-") as tmp:
            fn = _unpack(packed.function, Path(tmp))
            try:
                validate_function_project(fn)
                check_bundle(fn)
            except (FileNotFoundError, NotADirectoryError,
                    BundleRefused) as exc:
                text = str(exc).replace(str(fn) + os.sep, "").replace(
                    str(fn), "function/")
                submit._fail(f"function/: {text} Workpeg would refuse to "
                             "build this function, so nothing was "
                             "uploaded.")
    try:
        _local_build(packed, namespace)
    except Refused as exc:
        submit._fail(f"{exc} Nothing was uploaded.")

    if dry_run:
        print(f"{branch}:{version}, dry run: nothing was uploaded.")
        print(f"Peg: {len(packed.files)} files, {len(packed.archive):,} "
              f"bytes packed, sha256 {packed.sha256}")
        for name in packed.files:
            print(f"  {name}")
        if packed.left_out:
            print("Not part of the peg, so not packed: "
                  + ", ".join(packed.left_out))
        return 0

    api = _api(api)
    ref = f"{branch}:{version}"
    upload, row = _declare(api, peg, token, branch, version, packed, timeout)
    if row is not None:
        print(json.dumps(_public(row), indent=2))
        print(f"{ref} was already submitted with these bytes, so nothing "
              "was sent again.", file=sys.stderr)
        for line in _state_lines(row):
            print(line, file=sys.stderr)
        return 1 if state_of(row) == "failed" else 0
    _to_bucket(upload, packed, ref, timeout)
    try:
        done = _uploaded(api, peg, token, branch, version, timeout)
    except (requests.ConnectionError, requests.Timeout) as exc:
        # The bucket took the bytes; whether the registry recorded them is
        # what was lost. A run again settles it: a recorded version is
        # reported above, an unrecorded one is finished.
        submit._fail(f"The archive is in the bucket, but the registry's "
                     f"answer for {ref} was lost ({_plain(exc)}). It may "
                     "already have recorded the upload: `workpeg project "
                     f"status {ref}` says, and running the same command "
                     "again finishes it either way.")
    print(json.dumps(_public(done), indent=2))
    if state_of(done) in ("failed", "not_built"):
        # uploaded/ answers 200 with the row as it stands when it is no
        # longer uploading: another run, or a peg in review moving on,
        # failed it after these bytes reached the bucket. That is not a
        # submitted version, so say what the row says instead.
        for line in _state_lines(done):
            print(line, file=sys.stderr)
        return 1
    print(submitted_line(branch, version, done.get("sha256") or packed.sha256,
                         target), file=sys.stderr)
    return 0


# ---------------------------------------------------------------- reading

def _get(api: str, peg: str, token: str, tail: str, timeout: int):
    """The registry's JSON for a version route, or None for a version it
    does not have. A registry without the routes, and any other error
    status, ends the command (exit 1)."""
    code, answer = _call("GET", api, peg, token, tail, timeout)
    if code == 404:
        if _no_routes(answer):
            _no_versions_yet(api, peg, tail=tail)
        return None
    if code >= 400:
        submit._fail(f"The registry answered {code}: {_detail_of(answer)}",
                     code=1)
    if not isinstance(answer, dict):
        submit._fail(f"The registry answered something that is not a JSON "
                     f"object: {_plain(str(answer)[:200])}", code=1)
    return answer


def _when(value) -> str:
    try:
        moment = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return _plain(value) if value else "at an unknown time"
    if moment.tzinfo is not None:
        moment = moment.astimezone(timezone.utc)
    return moment.strftime("%Y-%m-%d %H:%M UTC")


def state_of(row: dict, live_version: Optional[str] = None) -> str:
    """One version's state, as a key of :data:`STATE_WORDS`, from the
    registry's ``build_status`` and ``review_status``. A decision on the
    review wins over the build; then the build, until it is built; then
    the review. Anything this SDK does not know is ``"unknown"``."""
    branch = row.get("branch")
    build, review = row.get("build_status"), row.get("review_status")
    if build == "uploading":
        return "uploading"
    if branch != submit.RELEASE_BRANCH:
        return "stored" if build == "stored" else "unknown"
    if review == "rejected":
        return "changes_requested"
    if review == "revoked":
        return "revoked"
    if build == "failed" and never_built(row):
        return "not_built"
    if build in ("queued", "building", "failed"):
        return build
    if build != "built":
        return "unknown"
    if review == "pending":
        return "in_review"
    if review == "approved":
        if not row.get("published_at"):
            return "approved"
        if live_version is not None and row.get("version") == live_version:
            return "live"
        return "published"
    return "unknown"


#: What ``versions`` prints for each state: the design's states, in words.
STATE_WORDS = {
    "uploading": "upload not finished",
    "stored": "development only",
    "queued": "queued for build",
    "building": "building",
    "failed": "build failed",
    "not_built": "never built",
    "in_review": "in review",
    "changes_requested": "changes requested",
    "approved": "approved",
    "published": "published",
    "live": "published, live",
    "revoked": "revoked",
}


def _words(row: dict, live_version: Optional[str]) -> str:
    state = state_of(row, live_version)
    if state != "unknown":
        return STATE_WORDS[state]
    build = _plain(row.get("build_status") or "no build status")
    review = row.get("review_status")
    return f"{build} ({_plain(review)})" if review else build


def status_line(row: dict) -> str:
    """One version's state, in the shape of :func:`submitted_line`."""
    branch, version = row.get("branch"), row.get("version")
    ref = _plain(f"{branch}:{version}")
    sha = f"sha256 {_short(row.get('sha256'))}"
    facts = (f"{sha}, uploaded {_when(row['uploaded_at'])}"
             if row.get("uploaded_at")
             else f"{sha}, declared {_when(row.get('created_at'))}")
    state = state_of(row)
    if state == "uploading":
        return (f"{ref} was declared and its upload not finished ({facts}). "
                f"Run `workpeg project submit {ref}` again to finish it.")
    if state == "stored":
        return (f"{ref} is stored for development only ({facts}); not "
                "built, reviewed or run on Workpeg.")
    if state == "queued":
        return (f"{ref} is queued for Workpeg's build ({facts}). It waits "
                "for review once it is built.")
    if state == "building":
        return (f"{ref} is building ({facts}). It waits for review once it "
                "is built.")
    if state == "failed":
        return (f"{ref} failed to build ({facts}). Fix it in a new version: "
                "a submitted version never changes.")
    if state == "not_built":
        return (f"{ref} was never built and cannot be reused ({facts}). "
                "Submit the peg as a new version: a submitted version "
                "never changes.")
    if state == "in_review":
        built = (f" built with SDK {_plain(row['target_sdk'])} and"
                 if row.get("target_sdk") else "")
        return (f"{ref} is{built} in review ({facts}). Workpeg publishes it "
                "only once it is approved.")
    if state == "approved":
        return f"{ref} is approved and not published yet ({facts})."
    if state in ("published", "live"):
        url = row.get("live_url")
        return (f"{ref} is published ({facts}). It is live at "
                f"{_plain(url)}." if url else f"{ref} is published ({facts}).")
    if state == "changes_requested":
        return (f"{ref} has changes requested ({facts}). Fix them in a new "
                "version: a submitted version never changes.")
    if state == "revoked":
        return (f"{ref} is revoked ({facts}). Workpeg no longer installs or "
                "publishes it.")
    return (f"{ref} is in a state this SDK does not name: "
            f"{_words(row, None)} ({facts}).")


def _block(title: str, text) -> list:
    lines = [line.rstrip() for line in _plain(text).splitlines()]
    while lines and not lines[-1]:
        lines.pop()
    return [title] + [f"  {line}" for line in lines] if lines else []


def _reader(path: str):
    project = Path(path).resolve()
    namespace = (_namespace(project) if (project / "workpeg.json").is_file()
                 else None)
    return _token_peg(namespace)


def _by_newest(rows: list) -> list:
    return sorted((r for r in rows if isinstance(r, dict)), key=lambda r: (
        str(r.get("created_at") or ""), str(r.get("version") or "")),
        reverse=True)


def main_status(ref: Optional[str], *, path: str = ".", as_json=False,
                api: Optional[str] = None, timeout: int = 60) -> int:
    """``workpeg project status [<ref>]``: 0, or 1 when the version is not
    on the registry."""
    token, peg = _reader(path)
    api = _api(api)
    if ref is not None:
        branch, version = submit.parse_ref(ref)
    else:
        # No ref: the newest release, or, before there is one, the newest
        # upload on any branch.
        rows = _by_newest((_get(api, peg, token, "", timeout) or {}).get(
            "versions") or [])
        if not rows:
            print(f"{peg} has no peg versions on the registry yet.")
            return 0
        newest = next((r for r in rows
                       if r.get("branch") == submit.RELEASE_BRANCH), rows[0])
        branch, version = str(newest["branch"]), str(newest["version"])
    detail = _get(api, peg, token, _version_tail(branch, version), timeout)
    if detail is None:
        print(f"ERROR: {branch}:{version} is not on the registry. `workpeg "
              "project versions` lists what is.", file=sys.stderr)
        return 1
    detail = _public(detail)
    if as_json:
        print(json.dumps(detail, indent=2, sort_keys=True))
        return 0
    for line in _state_lines(detail):
        print(line)
    return 0


def _state_lines(detail: dict) -> list:
    """:func:`status_line`, then a failed build's error and a reviewer's
    note, as plain text."""
    lines = [status_line(detail)]
    state = state_of(detail)
    if state == "failed":
        lines += _block("Build error:", detail.get("build_error") or "")
    elif state == "not_built":
        lines += _block("Why it was not built:", _why_not_built(detail))
    lines += _block("Reviewer's note:", detail.get("review_note") or "")
    return lines


def main_versions(*, path: str = ".", as_json=False,
                  api: Optional[str] = None, timeout: int = 60) -> int:
    """``workpeg project versions``: every peg version on the registry."""
    token, peg = _reader(path)
    api = _api(api)
    body = _public(_get(api, peg, token, "", timeout) or {})
    if as_json:
        print(json.dumps(body, indent=2, sort_keys=True))
        return 0
    live = body.get("live_version")
    rows = _by_newest(body.get("versions") or [])
    if not rows:
        print(f"{peg} has no peg versions on the registry yet.")
        return 0
    branches = {}
    for row in rows:
        branches.setdefault(_plain(row.get("branch")), []).append(row)
    order = sorted(branches, key=lambda b: (b != submit.RELEASE_BRANCH,
                                            b != submit.DEFAULT_BRANCH, b))
    width = max(len(_plain(r.get("version"))) for r in rows)
    words = max(len(w) for w in STATE_WORDS.values())
    for branch in order:
        print(branch)
        for row in branches[branch]:
            when = _when(row.get("uploaded_at") or row.get("created_at"))
            print(f"  {_plain(row.get('version')):<{width}}  "
                  f"{_words(row, live):<{words}}  {when}")
    return 0
